#include <iostream>

void process(int& x) {
    std::cout << "Processing " << x << std::endl;
}

int main() {
    int a = 10, b = 20, c = 30;

    // Using a lambda function
    auto processAll = [](int& x) { process(x); };
    processAll(a);
    processAll(b);
    processAll(c);

    // Using a function pointer
    void (*processPtr)(int&) = process;
    processPtr(a);
    processPtr(b);
    processPtr(c);

    return 0;
}
```

In this example, the `process` function is called with each of the variables `a`, `b`, and `c` using a lambda function and a function pointer. This approach allows you to run the same code on multiple variables in a concise manner.

